-- IN Website — constellation points seed
-- Generated by app/scripts/extract-stories.mjs from site/Constellation.EN.dc.html.

insert into public.constellation_points
  (id, title, by_line, format, topic, arc, month, caption, read_href, media_href, view_href,
   title_ko, by_line_ko, caption_ko, topic_ko)
values
  ('grandma-it-worked', '“Grandma, it worked!”', 'A grandmother', 'writing', 'Family', null, '2026-07', 'A grandson comes home breathless — he tried MEWE on his friends, and for the first time, watched it actually work.', '/story/all?story=grandma-it-worked', null, null, '“할머니, 됐어요!”', '한 할머니', '손자가 숨차게 집으로 뛰어 들어옵니다 — 친구들에게 MEWE를 시도해 봤고, 처음으로 그것이 실제로 작동하는 것을 지켜봤습니다.', '가족'),
  ('this-is-us', '“This is us”', 'A teacher', 'writing', 'Classroom', 'ME = WE', '2026-03', 'I stopped teaching and asked one real question. By the end, a boy pointed at what they’d made and said: this is us.', '/story/all?story=this-is-us', null, null, '“이게 우리예요”', '한 선생님', '가르치기를 멈추고 진짜 질문 하나를 던졌습니다. 끝날 무렵, 한 아이가 함께 만든 것을 가리키며 말했습니다: 이게 우리예요.', '교실'),
  ('connected', '“Perhaps we were already connected.”', 'Anonymous', 'music', 'Collective', null, '2026-02', 'A participant reflection, carried out of a ME=WE Core session.', '/story/all?story=connected', null, null, '“어쩌면 우리는 이미 연결되어 있었는지도.”', '익명', 'ME=WE 코어 세션에서 나온 한 참가자의 회고.', '콜렉티브'),
  ('two-hands', 'Two hands, one line', 'A participant', 'drawing', 'Collective', null, '2026-02', 'A drawing made during Möbius Making — where the ME and WE surfaces became one.', '/story/all?story=two-hands', null, null, '두 손, 하나의 선', '한 참가자', '뫼비우스 만들기에서 그려진 그림 — ME와 WE의 면이 하나가 된 곳.', '콜렉티브'),
  ('song-whole', 'A song for the whole', 'A collective', 'music', 'Collective', null, '2026-01', 'Recorded after a retreat — voices that learned to listen before they sang.', '/story/all?story=song-whole', null, null, '전체를 위한 노래', '한 콜렉티브', '리트릿 후 녹음된 노래 — 부르기 전에 듣는 법을 배운 목소리들.', '콜렉티브'),
  ('week-after', 'The week after the workshop', 'A participant', 'writing', 'Family', null, '2026-01', 'A participant writes about the small action they chose — and what it changed at home.', '/story/all?story=week-after', null, null, '워크숍 다음 주', '한 참가자', '한 참가자가 자신이 고른 작은 행동에 대해 씁니다 — 그것이 집에서 무엇을 바꿨는지.', '가족'),
  ('street-exp', 'A neighbor’s small experiment', 'A neighbor', 'writing', 'Neighbors', null, '2025-12', 'One person tried a single ME=WE action for a week — and wrote down what changed on their street.', '/story/all?story=street-exp', null, null, '어느 이웃의 작은 실험', '한 이웃', '한 사람이 일주일간 하나의 ME=WE 행동을 시도하고 — 자신의 거리에서 달라진 것을 적었습니다.', '이웃'),
  ('harmony', '“The harmony was already in them.”', 'A facilitator', 'music', 'Collective', null, '2025-12', 'Overheard after a singing circle — the group found the chord before anyone taught it.', '/story/all?story=harmony', null, null, '“화음은 이미 그들 안에 있었다.”', '한 퍼실리테이터', '노래 모임 후 우연히 들은 말 — 누가 가르치기 전에 그룹이 화음을 찾아냈습니다.', '콜렉티브'),
  ('noticed', 'A moment someone noticed ME=WE', 'Anonymous', 'photo', 'Noticed in the world', null, '2025-11', 'A photo of strangers becoming, briefly, one thing.', '/story/all?story=noticed', null, '/project-img/light-shadow-shift-women3.jpg', '누군가 ME=WE를 알아차린 순간', '익명', '낯선 이들이 잠시 하나가 되는 사진.', '세상에서 발견'),
  ('hasaad', 'Hasaad — food grown for neighbors', 'A UAE youth venture', 'video', 'Nature', null, '2025-11', 'A participant venture in organic food and farming, Dubai.', '/story/all?story=hasaad', 'https://youtu.be/Pl1IBR7fnTU', null, '하사드 — 이웃을 위해 기른 먹거리', 'UAE 청년 벤처', '두바이의 유기농 먹거리·농업 참가자 벤처.', '자연'),
  ('what-held', 'What held after the bootcamp', 'The UNC film team', 'video', 'Collective', null, '2025-10', 'A camera followed Nepali youth for two years — to see what lasted.', '/story/all?story=what-held', 'https://youtu.be/d1J4AECO_9g', null, '부트캠프 후에 남은 것', 'UNC 영상팀', '카메라가 네팔 청년들을 2년간 따라갔습니다 — 무엇이 지속되는지 보기 위해.', '콜렉티브'),
  ('circle-dance', 'A circle dance at closing', 'Anonymous', 'dance', 'Collective', null, '2025-10', 'Nobody planned it. The last session ended and the chairs moved themselves.', '/story/all?story=circle-dance', null, null, '마무리의 원무', '익명', '아무도 계획하지 않았습니다. 마지막 세션이 끝나자 의자들이 스스로 움직였습니다.', '콜렉티브'),
  ('plate', 'A plate for a neighbor', 'Rana', 'craft', 'Neighbors', null, '2025-09', 'Made in an afternoon, given the same evening.', '/story/all?story=plate', null, null, '이웃을 위한 접시', '라나', '한나절에 만들어, 그날 저녁에 건넸습니다.', '이웃'),
  ('soup', 'My grandmother’s soup, doubled', 'Anonymous', 'recipe', 'Family', null, '2025-09', 'The recipe says feeds six. She always made it feed twelve.', '/story/all?story=soup', null, null, '두 배로 끓인 할머니의 국', '익명', '조리법엔 6인분이라 적혀 있지만, 할머니는 늘 12인분을 만드셨습니다.', '가족'),
  ('wire-mobius', 'A Möbius strip in wire', 'A workshop group', 'symbol', 'Noticed in the world', null, '2025-08', 'Bent by four hands taking turns — one surface, no inside or outside.', '/story/all?story=wire-mobius', null, null, '철사로 만든 뫼비우스 띠', '워크숍 그룹', '네 손이 번갈아 구부린 것 — 안도 밖도 없는 하나의 면.', '세상에서 발견'),
  ('our-street', 'The street where we all live', 'Amina, age 11', 'drawing', 'Neighbors', null, '2025-08', 'Every house drawn with its door open.', '/story/all?story=our-street', null, null, '우리 모두가 사는 거리', '아미나, 11세', '모든 집이 문을 연 채로 그려져 있습니다.', '이웃'),
  ('mural', 'Flashlight mural, mid-shift', 'A retreat circle', 'photo', 'Collective', null, '2025-07', 'Shadow made visible by hand, after dark.', '/story/all?story=mural', null, '/project-img/shadow-shifter3.jpg', '손전등 벽화, 한창 그리던 중', '리트릿 서클', '어둠 속에서 손으로 드러낸 그림자.', '콜렉티브'),
  ('letter', 'A letter I wrote to myself', 'Anonymous', 'writing', 'Family', null, '2025-07', 'Opened a year later. Half of it had come true; the other half still asks.', '/story/all?story=letter', null, null, '나에게 쓴 편지', '익명', '1년 뒤에 열었습니다. 절반은 이루어졌고, 나머지 절반은 여전히 묻고 있습니다.', '가족'),
  ('farm-song', 'A farm-to-table song', 'Friends in Yamaguchi', 'music', 'Nature', null, '2025-06', 'Sung while carrying vegetables from the field to the table.', '/story/all?story=farm-song', null, null, '밭에서 식탁까지의 노래', '야마구치의 친구들', '밭에서 식탁으로 채소를 나르며 부른 노래.', '자연'),
  ('leaf', 'A found leaf, pressed', 'Anonymous', 'other', 'Nature', null, '2025-06', 'Carried back into the room beside a few words on reforming from within.', '/story/all?story=leaf', null, null, '주워서 눌러 둔 잎', '익명', '안에서부터 다시 빚어진다는 몇 마디 곁에 놓여 방으로 돌아왔습니다.', '자연'),
  ('dawn-yoga', 'Movement at dawn, day two', 'A retreat circle', 'dance', 'Nature', null, '2025-05', 'Two days spent in mind and heart, closed in the body.', '/story/all?story=dawn-yoga', null, null, '새벽의 움직임, 이틀째', '리트릿 서클', '마음과 머리로 보낸 이틀을, 몸으로 닫았습니다.', '자연'),
  ('pathfinder-journey', 'I had done it everywhere but home', 'Alia Ahmed', 'writing', 'I lived it', null, '2023-07', 'She had run social impact programs for years. It never occurred to her to point one at her own brothers.', '/story/all?story=pathfinder-journey', null, null, '집만 빼고 어디서나 해 왔다는 것', 'Alia Ahmed', '그녀는 수년간 소셜 임팩트 프로그램을 운영해 왔습니다. 그것을 자신의 형제들에게 향하게 할 생각은 한 번도 하지 못했습니다.', '내가 살아낸 것'),
  ('mewe-reflection', 'Reflections of a Pathfinder', 'Rajaa Bokhari', 'writing', 'Blog reflection', null, '2022-09', 'Two sessions of one Pathfinder cohort: five time zones discovering how closely their hopes aligned, then practising letting go of ego — the flip, from independence to interdependence.', '/story/all?story=mewe-reflection', null, null, '어느 패스파인더의 회고', 'Rajaa Bokhari', '한 패스파인더 기수의 두 세션: 다섯 시간대의 사람들이 서로의 바람이 얼마나 닮았는지 발견하고, 에고를 내려놓는 연습을 했습니다 — 독립에서 상호의존으로의 뒤집기.', '블로그 회고'),
  ('importance-of-connection', '“Now I can see the importance of connection”', 'Fr. Akhil Abrahim', 'writing', 'Blog reflection', null, '2022-09', 'A participant describes a meditation on letting go — and the moment ME+WE stopped being an idea.', '/story/all?story=importance-of-connection', null, null, '“이제 연결의 소중함이 보여요”', 'Fr. Akhil Abrahim', '한 참가자가 내려놓음에 대한 명상을 들려줍니다 — ME+WE가 관념이기를 멈춘 순간을.', '블로그 회고'),
  ('kulna-garden', 'Trying to find my place', 'Almanar Al Bastaki', 'writing', 'I lived it', null, '2021-11', 'A visual art student walked into a garden project to see what it was. She stayed three years and built a food forest.', '/story/all?story=kulna-garden', null, null, '내 자리를 찾아서', 'Almanar Al Bastaki', '시각예술을 배우던 학생이 무엇인지 궁금해 정원 프로젝트에 들어섰습니다. 3년을 머물렀고, 먹거리 숲을 지었습니다.', '내가 살아낸 것'),
  ('shy-to-leading', 'My father spent it on the village', 'Pabitra Majhi', 'writing', 'I lived it', null, '2018-09', 'He was a driver with savings meant for his daughters. He built a youth club instead — and took her with him.', '/story/all?story=shy-to-leading', null, null, '아버지는 그 돈을 마을에 썼습니다', 'Pabitra Majhi', '딸들을 위해 모아 둔 돈이 있던 운전기사였습니다. 그는 대신 청년 클럽을 지었고 — 딸을 데리고 갔습니다.', '내가 살아낸 것'),
  ('encouragement', 'More than her words', 'Jyoti', 'writing', 'I noticed it', null, '2017-09', 'She was unemployed and poor, and thought encouragement was the only thing she had to give.', '/story/all?story=encouragement', null, null, '그녀의 말보다 더 많은 것', '조티', '일자리도 돈도 없던 그녀는, 줄 수 있는 것이 격려뿐이라고 생각했습니다.', '내가 알아차린 것'),
  ('beehive', 'Taller than the Eiffel Tower', 'Shashank Pokharel', 'writing', 'I lived it', null, '2017-08', 'His first poem, written at eight. His first prototype, abandoned at twenty-one. Both taught the same thing.', '/story/all?story=beehive', null, null, '에펠탑보다 높이', 'Shashank Pokharel', '여덟 살에 쓴 첫 시. 스물한 살에 접은 첫 프로토타입. 둘 다 같은 것을 가르쳐 주었습니다.', '내가 살아낸 것'),
  ('homestay', 'The work that isn''t counted', 'Sajana Bhadel', 'writing', 'I lived it', null, '2017-08', 'Her village is a World Heritage Site. The women who hold it together don’t appear in any figure.', '/story/all?story=homestay', null, null, '셈해지지 않는 일', 'Sajana Bhadel', '그녀의 마을은 세계문화유산입니다. 그 마을을 지탱하는 여성들은 어떤 통계에도 나오지 않습니다.', '내가 살아낸 것'),
  ('shopkeeper', 'If someone can teach us', 'Shahadev Balami', 'writing', 'I noticed it', null, '2016-08', 'The power cuts out most afternoons in Parphing. A shopkeeper decided what to do with the hours it left him.', '/story/all?story=shopkeeper', null, null, '누군가 가르쳐 줄 수 있다면', 'Shahadev Balami', '파르핑에서는 오후마다 전기가 끊깁니다. 한 가게 주인은 남겨진 그 시간으로 무엇을 할지 결정했습니다.', '내가 알아차린 것'),
  ('birthday', 'The night the camp became a family', 'UNC2016', 'writing', 'I noticed it', null, '2016-07', 'Eighteen strangers, three days in. One of them had a birthday. Nobody organised what happened next.', '/story/all?story=birthday', null, null, '캠프가 가족이 된 밤', 'UNC2016', '낯선 열여덟 명, 사흘째. 그중 한 명의 생일이었습니다. 그다음에 일어난 일은 아무도 계획하지 않았습니다.', '내가 알아차린 것')
on conflict (id) do update set
  title = excluded.title, by_line = excluded.by_line, format = excluded.format,
  topic = excluded.topic, arc = excluded.arc, month = excluded.month,
  caption = excluded.caption, read_href = excluded.read_href,
  media_href = excluded.media_href, view_href = excluded.view_href,
  title_ko = excluded.title_ko, by_line_ko = excluded.by_line_ko,
  caption_ko = excluded.caption_ko, topic_ko = excluded.topic_ko;
